func (this *Hibachi) ParseMarket(market any) any {
	var marketId any = this.SafeString(market, "symbol")
	var numericId any = this.SafeNumber(market, "id")
	var marketType string = "swap"
	var baseId any = this.SafeString(market, "underlyingSymbol")
	var quoteId any = this.SafeString(market, "settlementSymbol")
	var base any = this.SafeCurrencyCode(baseId)
	var quote any = this.SafeCurrencyCode(quoteId)
	var settleId any = this.SafeString(market, "settlementSymbol")
	var settle any = this.SafeCurrencyCode(settleId)
	var symbol any = Add(Add(Add(Add(base, "/"), quote), ":"), settle)
	var created any = this.SafeIntegerProduct(market, "marketCreationTimestamp", 1000)
	return this.SafeMarketStructure(map[string]any{
		"id":             marketId,
		"numericId":      numericId,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       settleId,
		"type":           marketType,
		"spot":           false,
		"margin":         false,
		"swap":           true,
		"future":         false,
		"option":         false,
		"active":         IsEqual(this.SafeString(market, "status"), "LIVE"),
		"contract":       true,
		"linear":         true,
		"inverse":        false,
		"contractSize":   this.ParseNumber("1"),
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "underlyingDecimals"))),
			"price":  Divide(this.ParseNumber(this.SafeValue(this.SafeList(market, "orderbookGranularities", []any{}), 0)), 10000),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": this.SafeNumber(market, "minNotional"),
				"max": nil,
			},
		},
		"created": created,
		"info":    market,
	})
}

