func (this *Hibachi) HardcodedCurrencies() any {
	// Hibachi only supports USDT on Arbitrum at this time
	// We don't have an API endpoint to expose this information yet
	var result map[string]any = map[string]any{}
	var networks map[string]any = map[string]any{}
	var networkId string = "ARBITRUM"
	AddElementToObject(networks, networkId, map[string]any{
		"id":      networkId,
		"network": networkId,
		"limits": map[string]any{
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
			"deposit": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"active":   nil,
		"deposit":  nil,
		"withdraw": nil,
		"info":     map[string]any{},
	})
	var code any = this.SafeCurrencyCode("USDT")
	if IsTrue(!IsEqual(code, nil)) {
		AddElementToObject(result, code, this.SafeCurrencyStructure(map[string]any{
			"id":        "USDT",
			"name":      "USDT",
			"type":      "fiat",
			"code":      code,
			"precision": this.ParseNumber("0.000001"),
			"active":    true,
			"fee":       nil,
			"networks":  networks,
			"deposit":   true,
			"withdraw":  true,
			"limits": map[string]any{
				"deposit": map[string]any{
					"min": nil,
					"max": nil,
				},
				"withdraw": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"info": map[string]any{},
		}))
	}
	return result
}
func (this *Hibachi) ParseBalance(response any) any {
	var result map[string]any = map[string]any{
		"info": response,
	}
	// Hibachi only supports USDT on Arbitrum at this time
	var code any = this.SafeCurrencyCode("USDT")
	var account any = this.Account()
	AddElementToObject(account, "total", this.SafeString(response, "balance"))
	AddElementToObject(account, "free", this.SafeString(response, "maximalWithdraw"))
	if IsTrue(!IsEqual(code, nil)) {
		AddElementToObject(result, code, account)
	}
	return this.SafeBalance(result)
}

