func (this *Hibachi) ParseTicker(ticker any, optionalArgs ...any) any {
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var prices any = this.SafeDict(ticker, "prices")
	var stats any = this.SafeDict(ticker, "stats")
	var bid any = this.SafeNumber(prices, "bidPrice")
	var ask any = this.SafeNumber(prices, "askPrice")
	var last any = this.SafeNumber(prices, "tradePrice")
	var high any = this.SafeNumber(stats, "high24h")
	var low any = this.SafeNumber(stats, "low24h")
	var volume any = this.SafeNumber(stats, "volume24h")
	return this.SafeTicker(map[string]any{
		"symbol":        this.SafeSymbol(nil, market),
		"timestamp":     nil,
		"datetime":      nil,
		"bid":           bid,
		"ask":           ask,
		"last":          last,
		"high":          high,
		"low":           low,
		"bidVolume":     nil,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    nil,
		"quoteVolume":   volume,
		"info":          ticker,
	}, market)
}
func (this *Hibachi) ParseTrade(trade any, optionalArgs ...any) any {
	// public fetchTrades:
	//      {
	//          "price": "3512.431902",
	//          "quantity": "1.414780098",
	//          "takerSide": "Buy",
	//          "timestamp": 1712692147
	//      }
	//
	// private fetchMyTrades:
	//      {
	//          "askAccountId": 221,
	//          "askOrderId": 589168494921909200,
	//          "bidAccountId": 132,
	//          "bidOrderId": 589168494829895700,
	//          "fee": "0.000477",
	//          "id": 199511136,
	//          "orderType": "MARKET",
	//          "price": "119257.90000",
	//          "quantity": "0.0000200000",
	//          "realizedPnl": "-0.000352",
	//          "side": "Sell",
	//          "symbol": "BTC/USDT-P",
	//          "timestamp": 1752543391
	//      }
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(trade, "symbol")
	market = this.SafeMarket(marketId, market)
	var symbol any = GetValue(market, "symbol")
	var id any = this.SafeString(trade, "id")
	var price any = this.SafeString(trade, "price")
	var amount any = this.SafeString(trade, "quantity")
	var timestamp any = this.SafeIntegerProduct(trade, "timestamp", 1000)
	var cost any = Precise.StringMul(price, amount)
	var side any = nil
	var fee any = nil
	var orderType any = nil
	var orderId any = nil
	var takerOrMaker any = nil
	if IsTrue(IsEqual(id, nil)) {
		// public trades
		side = this.SafeStringLower(trade, "takerSide")
		takerOrMaker = "taker"
	} else {
		// private trades
		side = this.SafeStringLower(trade, "side")
		fee = map[string]any{
			"cost":     this.SafeString(trade, "fee"),
			"currency": "USDT",
		}
		orderType = this.SafeStringLower(trade, "orderType")
		if IsTrue(IsEqual(side, "buy")) {
			orderId = this.SafeString(trade, "bidOrderId")
		} else {
			orderId = this.SafeString(trade, "askOrderId")
		}
	}
	return this.SafeTrade(map[string]any{
		"id":           id,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"side":         side,
		"price":        price,
		"amount":       amount,
		"cost":         cost,
		"order":        orderId,
		"takerOrMaker": takerOrMaker,
		"type":         orderType,
		"fee":          fee,
		"info":         trade,
	}, market)
}

